// Generated by Cypress Author on 2026-10-23 for IMP-03 in the main application.
import {
  preparePractice,
  openPractice,
  writeCode,
  correctCode,
  attemptsEndpoint,
  confirmSubmit,
  solutionPath,
} from './practice-support';
import identityFixture from '../../fixtures/foundation/identity.json';

describe('IMP-03 · intentos persistentes e historia propia', () => {
  let releaseHeldResponse: (() => void) | undefined;
  afterEach(() => {
    releaseHeldResponse?.();
    releaseHeldResponse = undefined;
  });
  it('IMP03-03 · Cancelar y confirmar → solo envía el código confirmado y protege pruebas ocultas', () => {
    preparePractice().then((fixture) => {
      let calls = 0;
      cy.intercept('POST', `**${attemptsEndpoint(fixture)}`, (request) => {
        calls++;
        request.continue((response) => {
          response.setDelay(1000);
        });
      }).as('submit');
      openPractice(fixture);
      const code =
        'function solve() { console.log("salida visible"); return 3; }';
      writeCode(code);
      cy.get('[data-cy="submit-code"]').click();
      cy.get('[data-cy="cancel-submit"]').click();
      cy.get('[role="dialog"]').should('not.exist');
      cy.then(() => expect(calls).to.eq(0));
      cy.get('[data-cy="solution-code"]').should('have.value', code);
      confirmSubmit();
      writeCode('// cambios posteriores protegidos');
      cy.wait('@submit', { responseTimeout: 45_000 }).then(
        ({ request, response }) => {
          expect(request.body.code).to.eq(code);
          expect(response!.statusCode).to.eq(201);
          expect(response!.body.data.code).to.eq(code);
        },
      );
      cy.get('[data-cy="attempt-diagnosis"]').should(
        'contain.text',
        'FAILED_TEST',
      );
      cy.get('[data-cy="saved-snapshot"]').should(
        'contain.text',
        'cambios posteriores',
      );
      cy.get('[data-cy="attempt-history-row"]').should('have.length', 1);
      cy.get('[data-cy="activity-progress"]').should('contain.text', '0/1');
      cy.contains('777113').should('not.exist');
      cy.get('[data-cy="solution-code"]').should(
        'have.value',
        '// cambios posteriores protegidos',
      );
    });
  });
  it('IMP03-04 · Copiar, corregir y volver a enviar → conserva historia, compara y mantiene éxito previo', () => {
    preparePractice().then((fixture) => {
      cy.intercept('POST', `**${attemptsEndpoint(fixture)}`).as('submit');
      openPractice(fixture);
      writeCode('function solve() { return 0; }');
      confirmSubmit();
      cy.wait('@submit', { responseTimeout: 45_000 });
      cy.get('[data-cy="show-attempt"]').click();
      cy.get('[data-cy="copy-attempt"]').click();
      cy.get('[data-cy="confirm-copy"]').click();
      cy.get('[data-cy="solution-code"]').should('have.focus');
      writeCode(correctCode);
      confirmSubmit();
      cy.wait('@submit', { responseTimeout: 45_000 }).then(({ response }) => {
        expect(response!.body.data.previousAttemptId).to.be.a('string');
        expect(response!.body.data.technicalResult.diagnosisCode).to.eq(
          'SUCCESS',
        );
      });
      cy.get('[data-cy="activity-progress"]').should('contain.text', '1/1');
      cy.get('[data-cy="attempt-history-row"]').should('have.length', 2);
      cy.get('[data-cy="compare-attempt"]').check();
      cy.get('[data-cy="attempt-comparison"]').should('contain.text', '+1');
      cy.get('[data-cy="attempt-history"]').scrollIntoView();
      cy.screenshot('imp03-historial', { capture: 'viewport' });
      writeCode('function solve() { return -1; }');
      confirmSubmit();
      cy.wait('@submit', { responseTimeout: 45_000 });
      cy.get('[data-cy="activity-progress"]').should('contain.text', '1/1');
      cy.reload();
      cy.get('[data-cy="attempt-history-row"]').should('have.length', 3);
      cy.visit(
        `/academia/${fixture.organization.id}/clases/${fixture.classroom.id}`,
      );
      cy.get('[data-cy="activity-row"] [data-cy="activity-progress"]')
        .should('be.visible')
        .and('contain.text', '1/1');
      const activityPath = `/academia/${fixture.organization.id}/actividades/${fixture.activity.id}`;
      cy.get(`a[href="${activityPath}"]`).click();
      cy.location('pathname').should('eq', activityPath);
      cy.get('[data-cy="activity-progress"]')
        .should('be.visible')
        .and('contain.text', '1/1');
    });
  });
  it('IMP03-05 · Perder respuesta, cerrar y recargar → recupera exactamente un intento con su clave original sin editor', () => {
    preparePractice().then((fixture) => {
      let key: string | null;
      let attemptId: string;
      let lost = false;
      openPractice(fixture, 'student', (window) => {
        const original = window.fetch.bind(window);
        window.fetch = async (input, init) => {
          const response = await original(input, init);
          if (
            !lost &&
            String(input).endsWith(attemptsEndpoint(fixture)) &&
            init?.method === 'POST' &&
            response.status === 201
          ) {
            lost = true;
            key = new Headers(init.headers).get('Idempotency-Key');
            attemptId = (await response.clone().json()).data.attemptId;
            // The real transaction committed; only the browser delivery fails.
            throw new TypeError('Controlled lost acknowledgement');
          }
          return response;
        };
      });
      writeCode(correctCode);
      confirmSubmit();
      cy.get('[data-cy="recover-submit"]', { timeout: 45_000 }).should(
        'be.enabled',
      );
      cy.task<{ status: number }>(
        'academic:request',
        {
          role: 'teacher',
          path: `/activities/${fixture.activity.id}/close`,
          options: {
            method: 'POST',
            body: {},
            revision: fixture.activity.revision,
          },
        },
        { log: false },
      )
        .its('status')
        .should('eq', 200);
      cy.task('foundation:apiStop', null, { log: false });
      cy.task('foundation:apiStart', null, { log: false });
      cy.reload();
      cy.get('[data-cy="solution-code"]').should('not.exist');
      cy.intercept('POST', `**${attemptsEndpoint(fixture)}`).as('recovery');
      cy.get('[data-cy="recover-submit"]').click();
      cy.wait('@recovery', { responseTimeout: 45_000 }).then(
        ({ request, response }) => {
          expect(request.headers['idempotency-key']).to.eq(key);
          expect(response!.body.data.attemptId).to.eq(attemptId);
          expect(response!.body.data.code).to.eq(correctCode);
        },
      );
      cy.get('[data-cy="attempt-history-row"]').should('have.length', 1);
      cy.get('[data-cy="recover-submit"]').should('not.exist');
    });
  });
  it('IMP03-06 · Cerrar una actividad con intentos → historial propio accesible sin reabrir editor', () => {
    preparePractice().then((fixture) => {
      cy.intercept('POST', `**${attemptsEndpoint(fixture)}`).as('submit');
      openPractice(fixture);
      writeCode(correctCode);
      confirmSubmit();
      cy.wait('@submit', { responseTimeout: 45_000 });
      cy.task<{ status: number }>(
        'academic:request',
        {
          role: 'teacher',
          path: `/activities/${fixture.activity.id}/close`,
          options: {
            method: 'POST',
            body: {},
            revision: fixture.activity.revision,
          },
        },
        { log: false },
      )
        .its('status')
        .should('eq', 200);
      cy.visit(
        `/academia/${fixture.organization.id}/clases/${fixture.classroom.id}`,
      );
      cy.contains('No hay actividades disponibles en esta clase.').should(
        'be.visible',
      );
      cy.get('[data-cy="attempted-activities"]')
        .contains('a', 'Ver intentos:')
        .click();
      cy.location('pathname').should('eq', solutionPath(fixture));
      cy.get('[data-cy="solution-code"]').should('not.exist');
      cy.get('[data-cy="attempt-history-row"]').should('have.length', 1);
      cy.get('[data-cy="show-attempt"]').click();
      cy.get('[data-cy="attempt-diagnosis"]').should('contain.text', 'SUCCESS');
      cy.get('[data-cy="copy-attempt"]').should('be.disabled');
      cy.scrollTo('top');
      cy.screenshot('imp03-cerrada', { capture: 'viewport' });
      openPractice(fixture, 'secondStudent');
      cy.get('[data-cy="attempt-history-row"]').should('not.exist');
      cy.get('[data-cy="attempt-source"]').should('not.exist');
    });
  });
  it('IMP03-07 · Cerrar sesión y cambiar de cuenta con respuesta tardía → no muestra ni restaura código de la cuenta anterior', () => {
    preparePractice().then((fixture) => {
      let requestSignal: AbortSignal | null | undefined;
      const source =
        'function solve(a, b) { console.log("resultado privado tardío"); return a + b; }';
      openPractice(fixture, 'student', (window) => {
        const original = window.fetch.bind(window);
        window.fetch = async (input, init) => {
          const response = await original(input, init);
          if (
            String(input).endsWith(attemptsEndpoint(fixture)) &&
            init?.method === 'POST' &&
            response.status === 201
          ) {
            requestSignal = init.signal;
            // The real API committed. Hold only delivery to the first account.
            return new Promise<Response>((resolve) => {
              releaseHeldResponse = () => resolve(response);
            });
          }
          return response;
        };
      });
      writeCode(source);
      confirmSubmit();
      cy.wrap(null, { timeout: 45_000 }).should(() =>
        expect(
          releaseHeldResponse,
          'respuesta real confirmada y retenida',
        ).to.be.a('function'),
      );
      cy.contains('button', /^Cerrar sesión$/).click();
      cy.location('pathname').should('eq', '/acceso');
      cy.window().then((window) =>
        expect(
          Object.keys(window.sessionStorage).filter((key) =>
            key.startsWith('alunza:draft:'),
          ),
        ).to.have.length(0),
      );
      // Authenticate the other account without navigation or browser reload.
      cy.get('#email').type(identityFixture.users[5]!.email, { log: false });
      cy.env(['fixturePassword'], { log: false }).then(({ fixturePassword }) =>
        cy.get('#password').type(String(fixturePassword), {
          log: false,
          parseSpecialCharSequences: false,
        }),
      );
      cy.contains('button', /^Iniciar sesión$/).click();
      cy.location('pathname').should('eq', '/inicio');
      cy.then(() => {
        expect(requestSignal?.aborted).to.eq(true);
        releaseHeldResponse!();
        releaseHeldResponse = undefined;
      });
      cy.get('[data-cy="attempt-result"]').should('not.exist');
      cy.contains('resultado privado tardío').should('not.exist');
      cy.visit(solutionPath(fixture));
      cy.get('[role="alert"]').should('be.visible');
      cy.get('[data-cy="solution-code"]').should('not.exist');
      cy.get('[data-cy="attempt-history-row"]').should('not.exist');
      openPractice(fixture);
      cy.get('[data-cy="solution-code"]').should('not.have.value', source);
      cy.get('[data-cy="recover-submit"]').should('not.exist');
      cy.get('[data-cy="attempt-history-row"]').should('have.length', 1);
      cy.get('[data-cy="show-attempt"]').click();
      cy.get('[data-cy="attempt-detail"] summary').click();
      cy.get('[data-cy="attempt-source"]').should('have.text', source);
    });
  });
  it('IMP03-08 · Confirmar dos envíos y recibir respuestas invertidas → conserva snapshots y dos intentos distintos', () => {
    preparePractice().then((fixture) => {
      let ordinal = 0;
      const received: {
        ordinal: number;
        key: string | null;
        attemptId: string;
        code: string;
      }[] = [];
      openPractice(fixture, 'student', (window) => {
        const original = window.fetch.bind(window);
        window.fetch = async (input, init) => {
          const submission =
            String(input).endsWith(attemptsEndpoint(fixture)) &&
            init?.method === 'POST';
          const order = submission ? ordinal++ : -1;
          const response = await original(input, init);
          if (submission && response.status === 201) {
            const attempt = (await response.clone().json()).data;
            received.push({
              ordinal: order,
              key: new Headers(init.headers).get('Idempotency-Key'),
              attemptId: attempt.attemptId,
              code: attempt.code,
            });
            if (order === 0)
              return new Promise<Response>((resolve) => {
                releaseHeldResponse = () => resolve(response);
              });
          }
          return response;
        };
      });
      const firstCode = 'function solve() { return 0; }';
      writeCode(firstCode);
      confirmSubmit();
      cy.wrap(null, { timeout: 45_000 }).should(() =>
        expect(releaseHeldResponse, 'primer intento persistido').to.be.a(
          'function',
        ),
      );
      writeCode(correctCode);
      confirmSubmit();
      cy.get('[data-cy="attempt-result"]', { timeout: 45_000 }).should(
        'contain.text',
        'Intento #2 guardado',
      );
      cy.get('[data-cy="attempt-diagnosis"]').should('contain.text', 'SUCCESS');
      cy.then(() => {
        expect(received).to.have.length(2);
        expect(new Set(received.map((item) => item.key)).size).to.eq(2);
        expect(new Set(received.map((item) => item.attemptId)).size).to.eq(2);
        expect(received.find((item) => item.ordinal === 0)!.code).to.eq(
          firstCode,
        );
        expect(received.find((item) => item.ordinal === 1)!.code).to.eq(
          correctCode,
        );
        releaseHeldResponse!();
        releaseHeldResponse = undefined;
      });
      cy.get('[data-cy="pending-attempt"]').should('not.exist');
      cy.get('[data-cy="attempt-result"]').should(
        'contain.text',
        'Intento #2 guardado',
      );
      cy.get('[data-cy="attempt-history-row"]').should('have.length', 2);
      cy.get('[data-cy="activity-progress"]').should('contain.text', '1/1');
      cy.reload();
      cy.get('[data-cy="solution-code"]').should('have.value', correctCode);
      cy.get('[data-cy="attempt-history-row"]').should('have.length', 2);
      cy.contains('[data-cy="show-attempt"]', 'Ver intento #1').click();
      cy.get('[data-cy="attempt-detail"] summary').click();
      cy.get('[data-cy="attempt-source"]').should('have.text', firstCode);
    });
  });
});
